private static void adjustConstructors(CtRecord recordType, CtConstructor<Object> newConstructor) {
	if (newConstructor.isImplicit()) {
		for (CtConstructor<Object> constructor : recordType.getConstructors()) {
			// A compact constructor is the canonical constructor, so an implicit canonical
			// constructor generated by the compiler for the same record is redundant.
			if (hasSameParameters(newConstructor, constructor)
					|| (constructor.isCompactConstructor() && isCanonicalConstructor(recordType, newConstructor))) {
				return;
			}
		}
	} else {
		for (CtConstructor<Object> constructor : recordType.getConstructors()) {
			// Replace an implicit constructor when it matches the new one, either by parameters or
			// because the new compact constructor is the canonical constructor it stands in for.
			if (constructor.isImplicit()
					&& (hasSameParameters(newConstructor, constructor)
						|| (newConstructor.isCompactConstructor() && isCanonicalConstructor(recordType, constructor)))) {
				recordType.removeConstructor(constructor);
			}
		}
	}
	recordType.addConstructor(newConstructor);
}

private static boolean isCanonicalConstructor(CtRecord recordType, CtConstructor<Object> constructor) {
	Set<CtRecordComponent> components = recordType.getRecordComponents();
	List<CtParameter<?>> parameters = constructor.getParameters();
	if (components.size() != parameters.size()) {
		return false;
	}
	int i = 0;
	for (CtRecordComponent component : components) {
		CtTypeReference<?> componentType = component.getType();
		CtTypeReference<?> parameterType = parameters.get(i).getType();
		if (componentType == null || parameterType == null || !componentType.equals(parameterType)) {
			return false;
		}
		i++;
	}
	return true;
}

