cat > /tmp/dbg/Dbg7.java <<'EOF'
import spoon.Launcher;
import spoon.reflect.CtModel;
import spoon.reflect.declaration.*;
import spoon.reflect.reference.CtTypeReference;
import spoon.reflect.visitor.filter.TypeFilter;
import spoon.support.reflect.CtExtendedModifier;
import spoon.compiler.Environment;

public class Dbg7 {
  public static void main(String[] a) {
    Launcher l = new Launcher();
    l.getEnvironment().setComplianceLevel(16);
    l.addInputResource("/app/src/test/resources/records/MultiParameter.java");
    CtModel m = l.buildModel();
    System.out.println("PPMode=" + l.getEnvironment().getPrettyPrintingMode());
    CtRecord r = m.getElements(new TypeFilter<>(CtRecord.class)).get(0);
    for (CtField<?> f : r.getFields()) {
      CtTypeReference<?> t = f.getType();
      System.out.println("FIELD " + f.getSimpleName()
        + " fImpl=" + f.isImplicit() + " tImpl=" + (t==null?"?":t.isImplicit()));
      for (CtExtendedModifier mod : f.getExtendedModifiers())
        System.out.println("   mod " + mod.getKind() + " impl=" + mod.isImplicit());
      System.out.println("   toString=[" + f + "]");
    }
  }
}
EOF
