51. public class CtRecordImpl extends CtClassImpl<Object> implements CtRecord {
52. 	private static final String ABSTRACT_MODIFIER_ERROR =
53. 			"Abstract modifier is not allowed on record";
54. 	@MetamodelPropertyField(role = CtRole.RECORD_COMPONENT)
55. 	private Set<CtRecordComponent> components = new LinkedHashSet<>();
56. 
57. 	@Override
58. 	@DerivedProperty
59. 	public CtTypeReference<?> getSuperclass() {
60. 		return getFactory().Type().createReference("java.lang.Record");
61. 	}
62. 
63. 	@Override
64. 	@UnsettableProperty
65. 	public <C extends CtType<Object>> C setSuperclass(CtTypeReference<?> superClass) {
66. 		return (C) this;
67. 	}
68. 
69. 	@Override
70. 	public CtRecord addRecordComponent(CtRecordComponent component) {
71. 		if (component == null) {
72. 			return this;
73. 		}
74. 		component.setParent(this);
75. 		getFactory().getEnvironment().getModelChangeListener().onSetAdd(this, CtRole.RECORD_COMPONENT, components, component);
76. 		components.add(component);
77. 
78. 		if (getField(component.getSimpleName()) == null) {
79. 			// Implicit fields are inserted at index 0
80. 			// Preserve the same ordering as the one of record components
81. 			addField(components.size(), component.toField());
82. 		}
83. 		if (!hasMethodWithSameNameAndNoParameter(component)) {
84. 			addMethod(component.toMethod());
85. 		}
86. 		return this;
87. 	}
88. 
89. 	@Override
90. 	public CtRecord removeRecordComponent(CtRecordComponent component) {
91. 		getFactory().getEnvironment().getModelChangeListener().onSetDelete(this, CtRole.RECORD_COMPONENT, components, component);
92. 		components.remove(component);
93. 		if (getField(component.getSimpleName()) != null
94. 				&& getField(component.getSimpleName()).isImplicit()) {
95. 			typeMembers.remove(component.toField());
96. 		}
97. 		if (getMethods().contains(component.toMethod())) {
98. 			typeMembers.remove(component.toMethod());
99. 		}
100. 		return this;
101. 	}
102. 
103. 	@Override
104. 	public CtRecord createCanonicalConstructorIfMissing() {
105. 
106. 		CtTypeReference<?>[] typeReferences =
107. 			getRecordComponents().stream()
108. 				.map(CtTypedElement::getType)
109. 				.toList().toArray(new CtTypeReference[0]);
110. 
111. 		// If a canonical constructor is not already present, adds one. A compact constructor is
112. 		// itself the canonical constructor, so it must be treated as already present.
113. 		CtConstructor<?> constructor = getConstructor(typeReferences);
114. 		if (constructor == null && !hasCompactConstructor()) {
115. 			CtConstructor<?> canonical = getFactory().createConstructor();
116. 			canonical.setImplicit(true);
117. 			// Set the same visibility as the one of the record
118. 			if (hasModifier(ModifierKind.PUBLIC)) {
119. 				canonical.setExtendedModifiers(Set.of(CtExtendedModifier.implicit(ModifierKind.PUBLIC)));
120. 			} else if (hasModifier(ModifierKind.PROTECTED)) {
121. 				canonical.setExtendedModifiers(Set.of(CtExtendedModifier.implicit(ModifierKind.PROTECTED)));
122. 			} else if (hasModifier(ModifierKind.PRIVATE)) {
123. 				canonical.setExtendedModifiers(Set.of(CtExtendedModifier.implicit(ModifierKind.PRIVATE)));
124. 			}
125. 			CtBlock<?> body = getFactory().createBlock();
126. 			for (CtField<?> field: getFields()) {
127. 				if (field.isImplicit()) {
128. 					CtParameter<?> parameter = getFactory().createParameter();
129. 					CtTypeReference<?> type = getClonedType(field.getType());
130. 					parameter.setType(type);
131. 					parameter.setSimpleName(field.getSimpleName());
132. 					canonical.addParameter(parameter);
133. 					CtFieldReference<?> fieldReference = getFactory().createFieldReference();
134. 					fieldReference.setSimpleName(field.getSimpleName());
135. 					fieldReference.setType(getClonedType(field.getType()));
136. 					CtVariableAccess<?> write = getFactory().Code().createVariableWrite(fieldReference, false);
137. 					CtVariableReference<?> writeRef = write.getVariable();
138. 					CtVariableAccess<?> read = getFactory().Code().createVariableRead(parameter.getReference(), false);
139. 					@SuppressWarnings({"rawtypes", "unchecked"})
140. 					CtAssignment<?, ?> assignment = getFactory().Code().createVariableAssignment((CtVariableReference) writeRef, false, read);
141. 					body.addStatement(assignment);
142. 				}
143. 			}
144. 			canonical.setBody(body);
145. 			addTypeMember(canonical);
146. 		}
147. 
148. 		return this;
149. 	}
150. 
151. 	private boolean hasCompactConstructor() {
152. 		for (CtConstructor<Object> constructor : getConstructors()) {
153. 			if (constructor.isCompactConstructor()) {
154. 				return true;
155. 			}
156. 		}
157. 		return false;
158. 	}
159. 
160. 	private @Nullable CtTypeReference<?> getClonedType(CtTypeReference<?> type) {
161. 		return type != null ? type.clone() : null;
162. 	}
163. 
164. 	@Override
165. 	public Set<CtRecordComponent> getRecordComponents() {
166. 		return Collections.unmodifiableSet(components);
167. 	}
168. 
169. 	@Override
170. 	public void accept(CtVisitor v) {
171. 		v.visitCtRecord(this);
172. 	}
173. 
174. 	@Override
175. 	public <C extends CtType<Object>> C addTypeMemberAt(int position, CtTypeMember member) {
176. 		// a record can have only implicit instance fields and this is the best point to preserve the invariant
177. 		// because there are multiple ways to add a field to a record
178. 		String memberName = member.getSimpleName();
179. 
180. 		if (member instanceof CtField && !member.isStatic()) {
181. 			member.setImplicit(true);
182. 			getAnnotationsWithName(memberName, ElementType.FIELD).forEach(member::addAnnotation);
183. 		}
184. 		if (member instanceof CtMethod && member.isImplicit()) {
185. 			getAnnotationsWithName(memberName, ElementType.METHOD).forEach(member::addAnnotation);
186. 		}
187. 		if (member instanceof CtConstructor && member.isImplicit()) {
188. 			for (CtParameter<?> parameter : ((CtConstructor<?>) member).getParameters()) {
189. 				getAnnotationsWithName(parameter.getSimpleName(), ElementType.PARAMETER).forEach(parameter::addAnnotation);
190. 			}
191. 
192. 		}
193. 		if (member instanceof CtMethod && (member.isAbstract() || member.isNative())) {
194. 			JLSViolation.throwIfSyntaxErrorsAreNotIgnored(this, String.format("%s method is native or abstract, both is not allowed",
195. 				memberName));
196. 		}
197. 		if (member instanceof CtAnonymousExecutable && !member.isStatic()) {
198. 			JLSViolation.throwIfSyntaxErrorsAreNotIgnored(this, "Instance initializer is not allowed in a record (JLS 17 $8.10.2)");
199. 		}
200. 		return super.addTypeMemberAt(position, member);
201. 	}
202. 
203. 	private List<CtAnnotation<?>> getAnnotationsWithName(String name, ElementType elementType) {
204. 		List<CtAnnotation<?>> result = new ArrayList<>();
205. 		for (CtRecordComponent component : components) {
206. 			if (component.getSimpleName().equals(name)) {
207. 				for (CtAnnotation<? extends Annotation> annotation : component.getAnnotations()) {
208. 					CtType<?> annotationType = annotation.getAnnotationType().getTypeDeclaration();
209. 					// TODO: this is not the best way to handle this, but it's the best we can do for now
210. 					if (annotationType != null) {
211. 						Target target = annotationType.getAnnotation(Target.class);
212. 						// https://docs.oracle.com/javase/specs/jls/se19/html/jls-9.html#jls-9.6.4.1
213. 						// If an annotation of type java.lang.annotation.Target is not present on the declaration of
214. 						// an annotation interface A, then A is applicable in all declaration contexts and in no
215. 						// type contexts.
216. 						if (target == null && elementType == ElementType.TYPE_USE) {
217. 							continue;
218. 						}
219. 						if (target == null || Arrays.stream(target.value()).anyMatch(e -> e == elementType)) {
220. 							result.add(annotation.clone());
221. 						}
222. 					}
223. 				}
224. 			}
225. 		}
226. 		return result;
227. 	}
228. 
229. 	@Override
230. 	public <C extends CtType<Object>> C setFields(List<CtField<?>> fields) {
231. 		super.setFields(fields);
232. 		for (CtRecordComponent component : components) {
233. 			if (getField(component.getSimpleName()) == null) {
234. 				addField(component.toField());
235. 			}
236. 		}
237. 		return (C) this;
238. 	}
239. 
240. 	@Override
241. 	public <C extends CtType<Object>> C setMethods(Set<CtMethod<?>> methods) {
242. 		super.setMethods(methods);
243. 		for (CtRecordComponent component : components) {
244. 			if (!hasMethodWithSameNameAndNoParameter(component)) {
245. 				addMethod(component.toMethod());
246. 			}
247. 		}
248. 		return (C) this;
249. 	}
250. 
251. 	private boolean hasMethodWithSameNameAndNoParameter(CtRecordComponent component) {
252. 		for (CtMethod<?> method : getMethodsByName(component.getSimpleName())) {
253. 			if (method.getParameters().isEmpty()) {
254. 				return true;
255. 			}
256. 		}
257. 		return false;
258. 	}
259. 
260. 
261. 	@Override
262. 	public <C extends CtType<Object>> C setTypeMembers(List<CtTypeMember> members) {
263. 		super.setTypeMembers(members);
264. 		for (CtRecordComponent component : components) {
265. 			if (hasMethodWithSameNameAndNoParameter(component)) {
266. 				addMethod(component.toMethod());
267. 			}
268. 			if (getField(component.getSimpleName()) == null) {
269. 				addField(component.toField());
270. 			}
271. 		}
272. 		return (C) this;
273. 	}
274. 
275. 	@Override
276. 	public <C extends CtModifiable> C addModifier(ModifierKind modifier) {
277. 		if (modifier.equals(ModifierKind.ABSTRACT)) {
278. 			JLSViolation.throwIfSyntaxErrorsAreNotIgnored(this, ABSTRACT_MODIFIER_ERROR);
279. 		}
280. 		return super.addModifier(modifier);
281. 	}
282. 
283. 	@Override
284. 	public <C extends CtModifiable> C setModifiers(Set<ModifierKind> modifiers) {
285. 		if (modifiers.contains(ModifierKind.ABSTRACT)) {
286. 			JLSViolation.throwIfSyntaxErrorsAreNotIgnored(this, ABSTRACT_MODIFIER_ERROR);
287. 		}
288. 		return super.setModifiers(modifiers);
289. 	}
290. 
291. 	@Override
292. 	public <C extends CtModifiable> C setExtendedModifiers(
293. 			Set<CtExtendedModifier> extendedModifiers) {
294. 		checkIfAbstractModifier(extendedModifiers);
295. 		return super.setExtendedModifiers(extendedModifiers);
296. 	}
297. 
298. 	private boolean isAbstract(CtExtendedModifier v) {
299. 		return v.getKind().equals(ModifierKind.ABSTRACT);
300. 	}
301. 
302. 	private void checkIfAbstractModifier(Set<CtExtendedModifier> extendedModifiers) {
303. 		for (CtExtendedModifier extendedModifier : extendedModifiers) {
304. 			if (isAbstract(extendedModifier)) {
305. 				JLSViolation.throwIfSyntaxErrorsAreNotIgnored(this, ABSTRACT_MODIFIER_ERROR);
306. 			}
307. 		}
308. 	}
309. 
310. 	@Override
311. 	public CtRecord setRecordComponents(Set<CtRecordComponent> components) {
312. 		getRecordComponents().forEach(this::removeRecordComponent);
313. 		components.forEach(this::addRecordComponent);
314. 		return this;
315. 	}
316. 
317. 	@Override
318. 	public <E extends CtElement> E setParent(CtElement parent) {
319. 		Set<CtExtendedModifier> extendedModifiers = new HashSet<>(getExtendedModifiers());
320. 		if (parent instanceof CtType) {
321. 			extendedModifiers.add(CtExtendedModifier.implicit(ModifierKind.STATIC));
322. 		} else {
323. 			extendedModifiers.remove(CtExtendedModifier.implicit(ModifierKind.STATIC));
324. 		}
325. 		setExtendedModifiers(extendedModifiers);
326. 		return super.setParent(parent);
327. 	}
328. 
329. 	@Override
330. 	public Set<CtTypeReference<?>> getPermittedTypes() {
331. 		return Set.of();
332. 	}
333. 
